// Progressive-disclosure prototype. All session data and mutations are simulated.
(() => {
const el=id=>document.getElementById(id);
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let screen='current',openGroups=new Set(),flat=true,search='',source='all',pending=[],chosen=base[0],editDraft='',historyTurn=13;
const titles=['需求与边界','接口约定','字段核对','查询路径','索引检查','缓存策略','历史数据','异常场景','测试基线','实现检查','阶段结论','压缩检查点','分页查询'];
const groups=[{id:'guidance',title:'长期指引',description:'约束助手如何回答和工作的规则',rows:base.filter(x=>x.role==='system'),excerpt:'依据代码和测试推进；保留数据；结论需要证据。'},
{id:'summary',title:'前情摘要',description:'较早对话压缩后留下的要点',rows:base.filter(x=>x.role==='summary'),excerpt:'已确认接口与数据边界，接下来验证分页与缓存。'},
{id:'recent',title:'最近对话',description:'你的要求、助手回复，以及工具查到的内容',rows:base.filter(x=>!['system','summary'].includes(x.role)),excerpt:'最近的要求：补上分页大小变化的回归测试，再验证缓存命中结果。'}];
document.body.innerHTML=`<header class="host"><strong>DeepSeek Harness</strong><span class="workspace-name muted">商品查询服务重构</span><span class="spacer"></span><span class="sample muted small">交互原型 · 模拟数据</span><button id="theme" aria-label="切换明暗主题">◐ 主题</button></header><nav class="host-tabs"><span class="muted">对话</span><span class="muted">轨迹</span><b>上下文</b></nav><main><div class="page-head"><div><h1>上下文</h1><p class="lead">完整阅读当前内容，围绕原文查看来源、变化与调整。</p></div><span class="spacer"></span><button id="queue" class="secondary" hidden>待应用 <span id="queueCount">0</span></button></div><nav class="modes" aria-label="查看目的"><button id="current" aria-pressed="true">当前内容</button><button id="changes" aria-pressed="false">变化记录</button></nav><div id="panel"></div></main><footer>模拟数据，仅演示界面。编辑和分叉不会改变真实会话。</footer><dialog id="inspect" aria-label="内容与操作"><button class="close" id="close" aria-label="关闭详情">×</button><div id="dialogContent"></div></dialog><div id="feedback" role="status" hidden></div>`;
function toast(text){el('feedback').textContent=text;el('feedback').hidden=false;clearTimeout(window.readerToast);window.readerToast=setTimeout(()=>el('feedback').hidden=true,3500)}
function item(x){return `<article class="context-entry" id="entry-${x.id}"><header class="entry-head"><strong>${e(x.label)}</strong><span>角色：${e(x.role==='summary'?'user':x.role)} · ${x.turn?'第 '+x.turn+' 轮':'系统部分'} · #${x.seq}</span><span class="spacer"></span><button class="plain-link" data-id="${x.id}">分析与操作</button></header><div class="entry-source">来源：${e(x.source)} · 当前保留</div><div class="context-text">${e(x.text)}</div>${x.code?'<pre>'+e(x.code)+'</pre>':''}${x.previous?'<aside class="context-note">'+e(x.previous)+' <button class="plain-link" data-change="'+x.id+'">查看变化关系</button></aside>':''}</article>`}
function refreshQueue(){el('queue').hidden=pending.length===0;el('queueCount').textContent=pending.length}
function render(){
el('current').setAttribute('aria-pressed',screen==='current');el('changes').setAttribute('aria-pressed',screen==='changes');
if(screen==='changes'){renderChanges();return}
el('panel').innerHTML=`<div class="status"><span class="dot"></span><span>当前日志推导 · 非最终请求</span><span class="spacer"></span><button id="usage" class="plain-link">本页 ${base.length} 条 · 估算 ${base.reduce((n,x)=>n+x.tokens,0)} Token</button></div><p class="scope-note">模拟上下文，以下展示样例中的全部正文与代码。真实请求配置、工具定义及非文本块尚未接入；工具结果为示例，不能视为实际文件全文。</p><div class="context-layout"><nav class="context-index" aria-label="上下文目录"><strong>定位内容</strong>${base.map(x=>'<a href="#entry-'+x.id+'">'+e(x.label)+(x.turn?' · '+x.turn:'')+'</a>').join('')}</nav><section class="context-document"><div class="searchrow"><input id="search" aria-label="搜索上下文" placeholder="搜索正文或来源…" value="${e(search)}"><select id="source" aria-label="筛选来源"><option value="all">全部角色</option><option value="system">系统</option><option value="summary">压缩摘要</option><option value="user">用户</option><option value="assistant">助手</option><option value="tool">工具</option></select></div><p id="coverage" class="order"></p><div id="flatList"></div></section></div>`;
el('usage').onclick=()=>show('<h2>当前内容统计</h2><p>统计范围：本页完整样例，共 '+base.length+' 条。Token 是样例估算值，不是实际请求用量。</p><dl>'+base.map(x=>'<dt>'+e(x.label)+' · #'+x.seq+'</dt><dd>'+x.tokens+' Token（样例估算）</dd>').join('')+'</dl>');
el('source').value=source;el('search').oninput=ev=>{search=ev.target.value;flatList()};el('source').onchange=ev=>{source=ev.target.value;flatList()};flatList();}
// Classification follows the existing CTM user/system/turn hierarchy.
// The fixture has no step IDs; do not invent a request grouping for it.
let readingMode='grouped';
const expandedClasses=new Set(['input','system','compression','turn-13']);
const expandedEntries=new Set();
function contextClasses(rows){
const result=[
{id:'input',title:'用户输入',description:'按出现顺序查看你的要求',rows:rows.filter(x=>x.role==='user')},
{id:'system',title:'系统提示词',description:'系统提供的指引与约束',rows:rows.filter(x=>x.role==='system')},
{id:'compression',title:'压缩记录',description:'当前保留的摘要，以及它替代的历史范围',rows:rows.filter(x=>x.role==='summary')}
];
const turns=[...new Set(rows.filter(x=>['assistant','tool'].includes(x.role)).map(x=>x.turn))].sort((a,b)=>a-b);
for(const turn of turns)result.push({id:'turn-'+turn,title:'轮次 '+turn,description:'助手回复、工具调用与结果 · 样例未提供步骤编号',rows:rows.filter(x=>['assistant','tool'].includes(x.role)&&x.turn===turn)});
return result.filter(g=>g.rows.length);
}
function groupedEntry(x){return `<details class="segment-disclosure" data-entry="${x.id}" ${expandedEntries.has(x.id)?'open':''}><summary><span>${e(x.label)} <span class="muted">· 第 ${x.turn||'—'} 轮 · #${x.seq}</span></span><span class="muted">${x.tokens} Token · 展开原文</span></summary>${item(x)}</details>`}
function renderGrouped(rows){return contextClasses(rows).map(g=>`<details class="context-class" id="class-${g.id}" data-class="${g.id}" ${expandedClasses.has(g.id)?'open':''}><summary><div><strong>${g.title}</strong><span class="class-description">${g.description}</span></div><span class="class-count">${g.rows.length} 条 · ${g.rows.reduce((n,x)=>n+x.tokens,0)} Token</span></summary><div class="class-body">${g.rows.map(groupedEntry).join('')}</div></details>`).join('')}
function bindGroups(){
document.querySelectorAll('[data-class]').forEach(d=>d.addEventListener('toggle',()=>{d.open?expandedClasses.add(d.dataset.class):expandedClasses.delete(d.dataset.class)}));
document.querySelectorAll('[data-entry]').forEach(d=>d.addEventListener('toggle',()=>{d.open?expandedEntries.add(d.dataset.entry):expandedEntries.delete(d.dataset.entry)}));
}
function readingControls(){
return `<div class="reading-controls"><div class="reading-switch" aria-label="阅读方式"><button id="groupedMode" aria-pressed="${readingMode==='grouped'}">分类阅读</button><button id="orderedMode" aria-pressed="${readingMode==='ordered'}">原始顺序</button></div><span class="spacer"></span><button class="plain-link" id="expandEverything">全部展开</button><button class="plain-link" id="collapseEverything">全部收起</button></div>`;
}
function bindReadingControls(){
el('groupedMode').onclick=()=>{readingMode='grouped';flatList()};el('orderedMode').onclick=()=>{readingMode='ordered';flatList()};
el('expandEverything').onclick=()=>{document.querySelectorAll('[data-class],[data-entry]').forEach(d=>d.open=true)};
el('collapseEverything').onclick=()=>{document.querySelectorAll('[data-class],[data-entry]').forEach(d=>d.open=false)};
}

function flatList(){
const rows=base.filter(x=>(source==='all'||x.role===source)&&[x.text,x.code||'',x.source].join(' ').toLowerCase().includes(search.toLowerCase()));
el('coverage').textContent=(rows.length===base.length?'全部 '+base.length+' 条已归类':'筛选结果 '+rows.length+' / '+base.length+' 条 · 当前不是完整视图')+(readingMode==='grouped'?' · 类内保持记录顺序；收起只影响显示':' · 按原始记录顺序连续展示');
el('flatList').innerHTML=readingControls()+(rows.length?(readingMode==='grouped'?renderGrouped(rows):rows.map(item).join('')):'<p>没有匹配的内容。</p>');
const nav=document.querySelector('.context-index');nav.innerHTML='<strong>上下文目录</strong>'+(readingMode==='grouped'?contextClasses(rows).map(g=>'<a href="#class-'+g.id+'">'+g.title+' · '+g.rows.length+'</a>').join(''):rows.map(x=>'<a href="#entry-'+x.id+'">'+e(x.label)+' · #'+x.seq+'</a>').join(''));
bindItems();bindGroups();bindReadingControls();
}
function bindItems(){document.querySelectorAll('[data-change]').forEach(b=>b.onclick=()=>{screen='changes';render();el('compression').click()});document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{chosen=base.find(x=>x.id===b.dataset.id);showDetail()})}
function show(html){el('dialogContent').innerHTML=html;if(!el('inspect').open)el('inspect').showModal()}
function showDetail(){const x=chosen;show(`<h2>${e(x.role==='user'?'你的要求':x.label)}</h2><p class="lead">这段内容仍保留在当前上下文中。</p><div class="readtext">${e(x.text)}</div>${x.code?`<pre>${e(x.code)}</pre>`:''}<div class="explain">${e(x.previous||'这条记录没有被替换或压缩，因此仍会作为后续对话的上下文。')}</div><details class="technical"><summary>来源与记录信息</summary><dl><dt>来源</dt><dd>${e(x.source)}</dd><dt>事件位置</dt><dd>#${x.seq}</dd><dt>记录角色</dt><dd>${e(x.role==='summary'?'user':x.role)}</dd><dt>Token 估算</dt><dd>约 ${x.tokens}</dd></dl><p>相似或重复提示只来自文本规则，不代表模型是否实际采纳。</p></details><div class="actions"><button class="secondary" id="copy">复制文本</button>${['user','assistant','system'].includes(x.role)?'<button class="primary" id="edit">调整这段内容</button>':''}</div>`);el('copy').onclick=async()=>{try{await navigator.clipboard.writeText(x.text);toast('已复制文本')}catch{toast('请选中文本后手动复制')}};if(el('edit'))el('edit').onclick=()=>{editDraft=x.text;edit()}}
function steps(n){return `<div class="steps">${[1,2,3].map((v,i)=>`${v===n?'<b>':'<span>'}${v} ${['编辑','预览影响','待应用'][i]}${v===n?'</b>':'</span>'}`).join(' → ')}</div>`}
function edit(){show(`<h2>调整这段内容</h2>${steps(1)}<p class="lead">先修改文字，下一步查看影响。现在不会改变会话。</p><h3>修改后的内容</h3><textarea id="draft" aria-label="修改后的内容">${e(editDraft)}</textarea><div class="actions"><button id="back" class="secondary">返回内容</button><button id="preview" class="primary">下一步：预览影响</button></div>`);el('back').onclick=showDetail;el('preview').onclick=()=>{editDraft=el('draft').value;preview()}}
function preview(){show(`<h2>这次调整会改变什么？</h2>${steps(2)}<h3>修改前</h3><div class="diff before">${e(chosen.text)}</div><h3>修改后</h3><div class="diff after">${e(editDraft)}</div><p class="explain">${chosen.role==='assistant'?'助手原文会被替换内容覆盖，替换内容以用户角色记录。':chosen.role==='system'?'指引会在下次系统提示词组装时生效。':'替换这一条要求，其他内容保持原顺序。'} 加入队列后，仍需等到下次安全执行步骤才生效。</p><details class="technical"><summary>查看 Token 与缓存影响</summary><p>Token 变化约 ${Math.ceil(editDraft.length/2)-chosen.tokens}（示例估算）。从修改位置开始，缓存前缀可能失效；不承诺精确节省金额。</p></details><div class="actions"><button class="secondary" id="revise">返回修改</button><button class="primary" id="apply">确认加入待应用</button></div>`);el('revise').onclick=edit;el('apply').onclick=()=>{pending.push({id:chosen.id,text:editDraft});refreshQueue();show(`<h2>已加入待应用</h2>${steps(3)}<p>这段修改尚未生效。实际插件会在写入会话日志后显示“已应用”。</p><p class="explain">这里是模拟队列，不会写入真实会话。</p><div class="actions"><button id="done" class="primary">回到当前内容</button></div>`);el('done').onclick=()=>el('inspect').close()}}
function queue(){show(`<h2>等待应用的修改</h2><p class="lead">这里只显示你已经确认的调整。</p>${pending.map(x=>`<div class="queue-row"><p>${e(x.text)}</p><span class="tag">待应用 · 模拟</span></div>`).join('')}<div class="actions"><button id="clear" class="secondary">取消这些修改</button></div>`);el('clear').onclick=()=>{pending=[];refreshQueue();el('inspect').close()}}
function renderChanges(){el('panel').innerHTML=`<p class="changes-intro">这里解释当前内容是怎样形成的。查看记录不会改变会话。</p><section class="change"><span class="tag">第 14 轮 · 新增</span><h2>你补充了新的要求</h2><p>${e(base.at(-1).text)}</p><button id="latest" class="plain-link small">查看这段内容 →</button></section><section class="change"><span class="tag">第 12 轮 · 压缩</span><h2>较早的对话被整理成摘要</h2><p>第 1–11 轮的较早内容移出了当前上下文，留下关键结论。原文仍保存在历史记录中。</p><button id="compression" class="plain-link small">查看压缩前后 →</button></section><details class="history-picker" id="historyPicker"><summary>查看某一轮结束时的内容，或从那里继续</summary><label class="small" for="historyTurn">已完成轮次</label><br><select id="historyTurn">${titles.map((t,i)=>`<option value="${i+1}">${i+1} · ${t}</option>`).join('')}</select><div id="historyRead" class="history-read"></div></details>`;el('latest').onclick=()=>{chosen=base.at(-1);showDetail()};el('compression').onclick=()=>show(`<h2>较早对话 → 前情摘要</h2><p class="lead">第 12 轮发生了这次变化。</p><h3>移出当前上下文</h3><p>第 1–11 轮的较早对话，仍保存在历史记录中。</p><h3>现在保留的摘要</h3><div class="explain">${e(base.find(x=>x.role==='summary').text)}</div><details class="technical"><summary>查看记录信息</summary><p>来源：官方压缩 · 事件 #160。此原型仅展示压缩关系，不包含真实历史原文。</p></details>`);el('historyTurn').value=historyTurn;el('historyTurn').onchange=ev=>{historyTurn=Number(ev.target.value);history()};history()}
function history(){el('historyRead').innerHTML=`<span class="tag">第 ${historyTurn} 轮结束时 · 只读</span><p>${historyTurn<12?'当时的较早对话尚未被摘要替代。':'当时已保留前情摘要。'}${historyTurn===13?'分页查询的检查已完成，尚未收到第 14 轮的新要求。':''}</p><button class="secondary" id="compare">与当前比较</button> <button class="primary" id="fork">从这里继续新对话</button>`;el('compare').onclick=()=>show(`<h2>与当前相比，发生了什么？</h2><p class="lead">第 ${historyTurn} 轮结束时 → 当前</p><h3>新增内容</h3>${base.filter(x=>x.turn>historyTurn&&x.role!=='summary').map(x=>`<p>${e(x.text)}</p>`).join('')}${historyTurn<12?'<h3>内容压缩</h3><p>第 1–11 轮的较早内容被前情摘要替代，原文仍在历史记录中。</p>':''}<p class="technical">此示例只演示变化关系；不冒充完整历史请求。</p>`);el('fork').onclick=fork}
function fork(){show(`<h2>从第 ${historyTurn} 轮继续新对话</h2><p>会创建一个分叉，保留到这一轮的历史。原会话保持不变。</p><h3>新对话的输入草稿</h3><textarea id="forkDraft" aria-label="新对话的输入草稿">请沿用已确认的约束，尝试另一个实现方案。</textarea><p class="small muted">只放入草稿，不自动发送；不会隐式复制附件。</p><div class="actions"><button id="cancelFork" class="secondary">取消</button><button id="confirmFork" class="primary">模拟创建新对话</button></div>`);el('cancelFork').onclick=()=>el('inspect').close();el('confirmFork').onclick=()=>{el('inspect').close();toast('已模拟创建分叉；没有创建真实会话或发送消息。')}}
el('current').onclick=()=>{screen='current';render()};el('changes').onclick=()=>{screen='changes';render()};el('theme').onclick=()=>document.body.toggleAttribute('data-ds-dark-theme');el('close').onclick=()=>el('inspect').close();el('queue').onclick=queue;render();
})();
